import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class CodeForces {
    public static void main(String[] args) throws IOException {
        Input.init();
        long n1;
        long n2;
        int n;
        long[] ab = new long[2];
        Input.Next(ab);
        n1 = ab[0];
        n2 = ab[1];
        int[] ni = new int[1];
        Input.Next(ni);
        n = ni[0];
        int idx = (n - 1) % 6;
        boolean neg = false;
        long current = n1;
        if (idx >= 3) {
            neg = true;
            idx = idx - 3;
        }

        if (idx == 1) {
            current = n2;
        } else if (idx == 2) {
            current = n2 - n1;
        }

        if (neg) {
            current = current * -1;
        }

        long mod = 1000000007;
        System.out.println((current % mod + mod) % mod);
    }

    public static int GetLastChildGoingHome(int[] inputs, int candies) {
        for (int i = 0; i < inputs.length; i++) {
            inputs[i] = inputs[i] % candies == 0 ? inputs[i] / candies : ((inputs[i] / candies) + 1);
        }

        int last = 0;
        int lastIdx = 0;

        for (int i = 0; i < inputs.length; i++) {
            if (inputs[i] >= last) {
                last = inputs[i];
                lastIdx = i;
            }
        }

        return lastIdx + 1;
    }
}

